{
  "findings": [
    {
      "check_id": "CKV_AZURE_35",
      "title": "Ensure default network access rule for Storage Accounts is set to deny",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "MEDIUM",
      "explanation": "The default network access rule is set to 'Allow', which permits unrestricted access to the storage account. This increases the risk of unauthorized access."
    },
    {
      "check_id": "AVD-AZU-0010",
      "title": "Network rules do not allow bypass for Microsoft Services",
      "resource": "azurerm_storage_account_network_rules.notification_storage_rules",
      "severity": "HIGH",
      "explanation": "Trusted Microsoft Services are not allowed to bypass the network rules. This can cause disruptions in services that rely on access to the storage account."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account_network_rules\" \"notification_storage_rules\" {\n  storage_account_id = azurerm_storage_account.notification_storage.id\n  default_action     = \"Deny\"\n  ip_rules           = [\"127.0.0.1\"]\n  bypass             = [\"Metrics\", \"Logging\", \"AzureServices\"]\n}",
  "fix_summary": "Set the default network access rule to 'Deny' to restrict unauthorized access and added 'AzureServices' to the bypass list to allow trusted Microsoft Services to access the storage account."
}
